def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rows = [r for r in range(h) if len(set(grid[r])) == 1]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    for r in rows:
        out[r] = [2] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
